    "tour.sowdoc.actions.desc": "บันทึกร่าง / พิมพ์ / ทำสำเนา (ระบบถามเลขใหม่) / แก้ไข (ต่อ -R อัตโนมัติ) / ทวงเลข PO / สร้างใบส่งมอบสินค้า / อัปเดตข้อมูลจากใบเสนอราคา และส่งขออนุมัติ — ปุ่มที่เห็นขึ้นกับสถานะและสิทธิ์",
