    "tour.sowdoc.actions.title": "All document actions",
    "tour.sowdoc.actions.desc": "Save draft / print / duplicate (asks for a new number) / rewrite (auto -R suffix) / chase PO / create a delivery order / refresh from the quotation, plus submit-for-approval — what you see depends on status and permissions.",
    "tour.sowdoc.completion.title": "Completion indicator",
